actionConfiguration.body:
select *
from public.update_quote_header(
	{{ Number(appsmith.store.selectedQuoteEventId || 0) }}::bigint,

	nullif(
		{{ (inpQuoReference.text || "").trim() }},
		''
	)::text,

	{{
	dateQuoValidUntil.selectedDate
	? moment(dateQuoValidUntil.selectedDate).format("YYYY-MM-DD")
	: null
	}}::date,

	{{ selQuoPricingMode.selectedOptionValue || "per_menu" }}::text,

	{{
	inpQuoEventPriceTotal.text !== "" &&
	inpQuoEventPriceTotal.text !== null &&
	inpQuoEventPriceTotal.text !== undefined
	? Number(inpQuoEventPriceTotal.text)
	: null
	}}::numeric,

	{{
	inpServiceCharge.text !== "" &&
	inpServiceCharge.text !== null &&
	inpServiceCharge.text !== undefined
	? Number(inpServiceCharge.text)
	: null
	}}::numeric,

	{{
	datQuoFinalDueDate.selectedDate
	? moment(datQuoFinalDueDate.selectedDate).format("YYYY-MM-DD")
	: null
	}}::date,

	nullif(
		{{
		rteQuoteCustomerNotes.text ||
		rteQuoteCustomerNotes.value ||
		""
		}},
		''
	)::text,

	nullif(
		{{
		rteQuoteInternalNotes.text ||
		rteQuoteInternalNotes.value ||
		""
		}},
		''
	)::text,

	nullif(
		{{
		rteQuoteTerms.text ||
		rteQuoteTerms.value ||
		""
		}},
		''
	)::text,

	nullif(
		{{ inpQuoVnuInstructions.text || "" }},
		''
	)::text
);
